<span class="line">        <span class="token keyword">print</span><span class="token punctuation">(</span>face<span class="token punctuation">.</span>location<span class="token punctuation">,</span> face<span class="token punctuation">.</span>detection_confidence<span class="token punctuation">)</span></span>
