<span class="line">emotion_labels <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string">&quot;Neutral&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Happy&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Sad&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Surprise&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Fear&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Disgust&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Anger&quot;</span><span class="token punctuation">]</span></span>
